umber of notes/bills\nfor i, el in enumerate(elements):\n    content = str(el.get('content', ''))\n    if 'pieces' in content.lower() and 'circulation' in content.lower():\n        print(f'Element {i}: {el.get(\\\"type\\\")}')\n        print(content[:800])\n        print('---')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
